// Agent platforms: one source, a generated configuration per platform, drift-checked. (ADR-019)
//
// Three open standards carry most of the integration: AGENTS.md (instructions), Agent Skills (the
// workflows, .agents/skills — skills.mjs) and MCP (`eos mcp`, ADR-018). What is left differs per
// platform: where its MCP configuration lives, the dialect of its pre-tool hook, and where it reads
// agents. This module is the table of those differences; `eos agents sync` renders it for the
// declared platforms (`agentPlatforms`; absent: copilot, claude and antigravity — the files in
// .agents/, .github/, .claude/ and .mcp.json), and `--check` fails CI on drift.
//
// Configuration files are SHARED with the team: .claude/settings.json holds their permissions,
// .mcp.json their other servers. So EOS owns ENTRIES, never such a file: it sets its own entry (the
// "eos" server, the hook that runs deny-dangerous.js), removes it when the platform is no longer
// declared, and deletes a file only when nothing else is left in it. Whole files are written only
// under names that are EOS's own (eos-* agents, the Kiro hook, the Cline script, the OpenCode
// plugin). Nothing is written or deleted through a symbolic link (skills.mjs linkOnPath), and trust
// stays with each platform: no auto-approve list, no trusted flag (ADR-018).
//
// The guardrail is one program, .github/hooks/deny-dangerous.js, run with `--format <platform>`. The
// Copilot hook is the template's own .github/hooks/guardrails.json; the agents' source is
// .github/agents/eos-*.agent.md, which Copilot reads as it is.
import { chmodSync, existsSync, mkdirSync, readFileSync, readdirSync, unlinkSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { AGENT_PLATFORMS, DEFAULT_AGENT_PLATFORMS } from '../../hooks/lib/project-config.mjs';
import { linkOnPath, skillFrontmatter, SKILL_MIRRORS } from './skills.mjs';

export const TIER2 = ['kiro', 'qwen', 'devin', 'opencode', 'cline'];
export const PLATFORM_NAMES = {
  copilot: 'GitHub Copilot', claude: 'Claude Code', codex: 'OpenAI Codex', cursor: 'Cursor',
  antigravity: 'Google Antigravity', gemini: 'Gemini CLI', kiro: 'Kiro', qwen: 'Qwen Code',
  devin: 'Windsurf / Devin Desktop', opencode: 'OpenCode', cline: 'Cline',
};
/** What each platform gets, and the one-time trust step it asks for — printed when one is added. */
export const PLATFORM_NOTES = {
  copilot: 'skills, agents (.github/agents) and the guardrail (.github/hooks) are the template\'s own; MCP via .mcp.json — VS Code asks you to trust the server before it first starts',
  claude: 'skills (.claude/skills copy), guardrail (.claude/settings.json), MCP (.mcp.json — Claude Code asks once to approve it); the orchestrators run as skills, not subagents',
  codex: 'skills and AGENTS.md natively; MCP in .codex/config.toml, guardrail in .codex/hooks.json, agents in .codex/agents — Codex reads .codex/ only in a trusted project, and asks you to approve each hook once (/hooks)',
  cursor: 'skills and AGENTS.md natively; guardrail for shell commands (.cursor/hooks.json), MCP in .cursor/mcp.json — Cursor asks per MCP call (Run Modes)',
  antigravity: 'skills and AGENTS.md natively; guardrail for run_command (.agents/hooks.json), MCP (.agents/mcp_config.json, Ask per call), agents (.agents/agents)',
  gemini: 'skills via the .agents/skills alias; .gemini/settings.json adds AGENTS.md to context.fileName, the guardrail (BeforeTool) and MCP — trust the folder first',
  kiro: 'Tier 2, not yet verified on a real installation: MCP (.kiro/settings/mcp.json) and guardrail (.kiro/hooks/eos-guardrail.json); AGENTS.md natively',
  qwen: 'Tier 2, not yet verified on a real installation: skills (.qwen/skills copy), guardrail and MCP (.qwen/settings.json); AGENTS.md natively',
  devin: 'Tier 2, not yet verified on a real installation: guardrail (.devin/hooks.v1.json) and MCP (.devin/mcp_config.json); AGENTS.md natively',
  opencode: 'Tier 2, not yet verified on a real installation: MCP (opencode.json) and the guardrail as a plugin (.opencode/plugins/eos-guardrail.js); AGENTS.md natively',
  cline: 'Tier 2, not yet verified on a real installation: the guardrail script (.clinerules/hooks/PreToolUse); Cline reads skills from .claude/skills (declare claude too) and MCP servers only from its global ~/.cline/mcp.json — add eos there yourself',
};
export const AGENTS_SOURCE = '.github/agents';
export const GENERATED_MARK = 'GENERATED by `eos agents sync`';

const SERVER_ARGS = ['.github/eos/eos.mjs', 'mcp'];
const server = (args = SERVER_ARGS) => ({ command: 'node', args: [...args] });
const hook = (format) => `node .github/hooks/deny-dangerous.js --format ${format}`;
const isOurs = (entry) => JSON.stringify(entry).includes('deny-dangerous.js');
const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const clone = (v) => JSON.parse(JSON.stringify(v));

// ----------------------------------------------------------------------- pieces of a JSON file

/** The object at `keys`, created on the way when `create`; a non-object in the way is a conflict. */
function objectAt(doc, keys, create) {
  let o = doc;
  for (const k of keys) {
    if (o[k] === undefined) { if (!create) return null; o[k] = {}; }
    if (!isObject(o[k])) throw new Error(`"${keys.join('.')}" is not an object`);
    o = o[k];
  }
  return o;
}

/** Delete the empty objects and arrays left along `keys`, innermost first. */
function prune(doc, keys) {
  for (let i = keys.length; i > 0; i -= 1) {
    const parent = objectAt(doc, keys.slice(0, i - 1), false);
    const v = parent?.[keys[i - 1]];
    const empty = Array.isArray(v) ? v.length === 0 : isObject(v) && Object.keys(v).length === 0;
    if (!parent || !empty) return;
    delete parent[keys[i - 1]];
  }
}

/** One value EOS owns at a key path: `mcpServers.eos`, `mcp.eos`, a named hook set. */
const entry = (keys, value) => ({
  set(doc) { objectAt(doc, keys.slice(0, -1), true)[keys.at(-1)] = clone(value); },
  unset(doc) {
    const parent = objectAt(doc, keys.slice(0, -1), false);
    if (parent && keys.at(-1) in parent) { delete parent[keys.at(-1)]; prune(doc, keys.slice(0, -1)); }
  },
});

/** EOS's element of a hook array: every element that runs deny-dangerous.js is EOS's. */
const hookEntry = (keys, value) => ({
  set(doc) {
    const parent = objectAt(doc, keys.slice(0, -1), true);
    const list = parent[keys.at(-1)] ?? [];
    if (!Array.isArray(list)) throw new Error(`"${keys.join('.')}" is not an array`);
    parent[keys.at(-1)] = [...list.filter((e) => !isOurs(e)), clone(value)];
  },
  unset(doc) {
    const parent = objectAt(doc, keys.slice(0, -1), false);
    const list = parent?.[keys.at(-1)];
    if (!Array.isArray(list) || !list.some(isOurs)) return;
    parent[keys.at(-1)] = list.filter((e) => !isOurs(e));
    prune(doc, keys);
  },
});

/** Gemini CLI reads AGENTS.md only when context.fileName names it. */
const GEMINI_FILES = ['AGENTS.md', 'GEMINI.md'];
const geminiContext = {
  set(doc) {
    const ctx = objectAt(doc, ['context'], true);
    const names = ctx.fileName === undefined ? [] : [].concat(ctx.fileName);
    if (!names.includes('AGENTS.md')) ctx.fileName = [...new Set(['AGENTS.md', ...(names.length ? names : ['GEMINI.md'])])];
  },
  unset(doc) {
    const ctx = objectAt(doc, ['context'], false);
    if (ctx && JSON.stringify(ctx.fileName) === JSON.stringify(GEMINI_FILES)) { delete ctx.fileName; prune(doc, ['context']); }
  },
};

// ---------------------------------------------------------------- the Codex TOML block (text)

const TOML_BEGIN = `# >>> eos — ${GENERATED_MARK}; edit .eos/project.json, not this block`;
const TOML_END = '# <<< eos';
const CODEX_MCP = [TOML_BEGIN, '[mcp_servers.eos]', 'command = "node"', `args = ${JSON.stringify(SERVER_ARGS).replace(/,/g, ', ')}`, TOML_END].join('\n');
const blockRe = () => /^# >>> eos\b[^\n]*\n[\s\S]*?^# <<< eos[ \t]*(?:\n|$)/m;
const tomlBlock = {
  set(text) {
    const outside = text.replace(blockRe(), '');
    if (/^\s*\[mcp_servers\.eos\]/m.test(outside)) throw new Error('declares [mcp_servers.eos] outside the EOS block — remove it, and EOS keeps its own');
    if (blockRe().test(text)) return text.replace(blockRe(), `${CODEX_MCP}\n`);
    return `${text}${text && !text.endsWith('\n') ? '\n' : ''}${text.trim() ? '\n' : ''}${CODEX_MCP}\n`;
  },
  unset(text) {
    if (!blockRe().test(text)) return text;
    const rest = text.replace(blockRe(), '');
    return rest.trim() ? rest.replace(/\n+$/, '\n') : '';
  },
};

// ------------------------------------------------------------------------------- the table

/**
 * Every configuration file EOS writes entries into. A piece is wanted when one of its platforms is
 * declared; otherwise its entry is removed (and the file, when nothing else is left in it).
 */
export const CONFIG_FILES = [
  { path: '.mcp.json', pieces: [{ platforms: ['copilot', 'claude'], ...entry(['mcpServers', 'eos'], { type: 'stdio', ...server() }) }] },
  {
    path: '.claude/settings.json',
    pieces: [{ platforms: ['claude'], ...hookEntry(['hooks', 'PreToolUse'], {
      matcher: 'Bash|Write|Edit|MultiEdit|NotebookEdit',
      hooks: [{ type: 'command', command: 'node "${CLAUDE_PROJECT_DIR:-.}/.github/hooks/deny-dangerous.js" --format claude', timeout: 30 }],
    }) }],
  },
  {
    path: '.agents/hooks.json',
    pieces: [{ platforms: ['antigravity'], ...entry(['eos-guardrail'], {
      PreToolUse: [{ matcher: 'run_command', hooks: [{ type: 'command', command: hook('antigravity'), timeout: 30 }] }],
    }) }],
  },
  { path: '.agents/mcp_config.json', pieces: [{ platforms: ['antigravity'], ...entry(['mcpServers', 'eos'], server()) }] },
  { path: '.codex/config.toml', toml: true, pieces: [{ platforms: ['codex'], ...tomlBlock }] },
  {
    path: '.codex/hooks.json',
    pieces: [{ platforms: ['codex'], ...hookEntry(['hooks', 'PreToolUse'], {
      matcher: 'Bash|apply_patch', hooks: [{ type: 'command', command: hook('codex'), timeout: 30 }],
    }) }],
  },
  {
    path: '.cursor/hooks.json',
    skeleton: { version: 1 },
    pieces: [{ platforms: ['cursor'], ...hookEntry(['hooks', 'beforeShellExecution'], { command: hook('cursor'), timeout: 30 }) }],
  },
  { path: '.cursor/mcp.json', pieces: [{ platforms: ['cursor'], ...entry(['mcpServers', 'eos'], server(['${workspaceFolder}/.github/eos/eos.mjs', 'mcp'])) }] },
  {
    path: '.gemini/settings.json',
    pieces: [
      { platforms: ['gemini'], ...hookEntry(['hooks', 'BeforeTool'], {
        matcher: 'run_shell_command|write_file|replace', hooks: [{ type: 'command', command: hook('gemini'), timeout: 30000 }],
      }) },
      { platforms: ['gemini'], ...entry(['mcpServers', 'eos'], server()) },
      { platforms: ['gemini'], ...geminiContext },
    ],
  },
  { path: '.kiro/settings/mcp.json', pieces: [{ platforms: ['kiro'], ...entry(['mcpServers', 'eos'], server()) }] },
  {
    path: '.qwen/settings.json',
    pieces: [
      { platforms: ['qwen'], ...hookEntry(['hooks', 'PreToolUse'], {
        matcher: 'run_shell_command|write_file|replace|edit', hooks: [{ type: 'command', command: hook('qwen'), timeout: 30 }],
      }) },
      { platforms: ['qwen'], ...entry(['mcpServers', 'eos'], server()) },
    ],
  },
  {
    path: '.devin/hooks.v1.json',
    pieces: [{ platforms: ['devin'], ...hookEntry(['PreToolUse'], { matcher: 'exec', hooks: [{ type: 'command', command: hook('devin'), timeout: 10 }] }) }],
  },
  { path: '.devin/mcp_config.json', pieces: [{ platforms: ['devin'], ...entry(['mcpServers', 'eos'], server()) }] },
  { path: 'opencode.json', pieces: [{ platforms: ['opencode'], ...entry(['mcp', 'eos'], { type: 'local', command: ['node', ...SERVER_ARGS] }) }] },
];

const KIRO_HOOK = {
  version: 'v1',
  hooks: [{ name: 'eos-guardrail', trigger: 'PreToolUse', action: { type: 'command', command: hook('kiro') }, timeout: 60 }],
};
const CLINE_HOOK = [
  '#!/bin/sh',
  `# ${GENERATED_MARK} — the EOS guardrail for Cline (PreToolUse). Edit .github/hooks/, not this file.`,
  'exec node "$(dirname "$0")/../../.github/hooks/deny-dangerous.js" --format cline',
  '',
].join('\n');
const OPENCODE_PLUGIN = [
  `// ${GENERATED_MARK} — the EOS guardrail for OpenCode (tool.execute.before). Edit .github/hooks/, not this file.`,
  "import { evaluateToolCall } from '../../.github/hooks/lib/secret-rules.mjs';",
  '',
  'export const EosGuardrail = async () => ({',
  "  'tool.execute.before': async (input, output) => {",
  '    const verdict = evaluateToolCall(JSON.stringify({ tool_name: input?.tool, tool_input: output?.args }));',
  "    if (verdict.decision === 'deny') throw new Error(verdict.reason);",
  '  },',
  '});',
  '',
].join('\n');

/** Whole files under names that are EOS's own. */
export const OWNED_FILES = [
  { path: '.kiro/hooks/eos-guardrail.json', platforms: ['kiro'], content: () => `${JSON.stringify(KIRO_HOOK, null, 2)}\n` },
  { path: '.clinerules/hooks/PreToolUse', platforms: ['cline'], mode: 0o755, content: () => CLINE_HOOK },
  { path: '.opencode/plugins/eos-guardrail.js', platforms: ['opencode'], content: () => OPENCODE_PLUGIN },
];

/**
 * Where a platform reads agents that Copilot does not. Claude Code's .claude/agents is left out on
 * purpose: VS Code reads it too, so every orchestrator would be listed twice in Copilot; Claude Code
 * runs the same workflows as skills.
 */
export const AGENT_DIRS = { antigravity: '.agents/agents', codex: '.codex/agents' };

const yamlString = (s) => JSON.stringify(String(s));
const tomlBasic = (s) => `"${String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n')}"`;
const tomlMultiline = (s) => (s.includes("'''") ? `"""\n${s.replace(/\\/g, '\\\\').replace(/"""/g, '""\\"')}"""` : `'''\n${s}'''`);

/** The orchestrator agents, read from their Copilot source. */
export function sourceAgents(root) {
  const dir = join(root, AGENTS_SOURCE);
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((f) => /^eos-[a-z0-9-]+\.agent\.md$/.test(f)).sort().map((file) => {
    const text = readFileSync(join(dir, file), 'utf8');
    const { fields } = skillFrontmatter(text);
    const body = text.replace(/^\uFEFF?---\r?\n[\s\S]*?\r?\n---(?:\r?\n|$)/, '').replace(/^\s*\n/, '');
    return { name: fields.name || file.replace(/\.agent\.md$/, ''), description: fields.description || '', body, source: `${AGENTS_SOURCE}/${file}` };
  });
}

const renderAgent = {
  antigravity: (a) => [
    '---', `name: ${a.name}`, `description: ${yamlString(a.description)}`, '---',
    `<!-- ${GENERATED_MARK} from ${a.source} — edit the source, not this file. -->`, '', a.body.trimEnd(), '',
  ].join('\n'),
  codex: (a) => [
    `# ${GENERATED_MARK} from ${a.source} — edit the source, not this file.`,
    `name = ${tomlBasic(a.name)}`, `description = ${tomlBasic(a.description)}`,
    `developer_instructions = ${tomlMultiline(`${a.body.trimEnd()}\n`)}`, '',
  ].join('\n'),
};
const agentFile = { antigravity: (n) => `${n}.md`, codex: (n) => `${n}.toml` };

// ------------------------------------------------------------------------------- planning

/** The platforms a project generates files for: declared, or the default set. */
export const declaredPlatforms = (project) => (Array.isArray(project?.agentPlatforms) ? project.agentPlatforms : DEFAULT_AGENT_PLATFORMS);

/**
 * Every path `eos agents sync` may write for some platform. `eos upgrade` leaves these out of its
 * three-way comparison and regenerates them for the project's own platforms instead.
 */
export function isGeneratedPath(path) {
  if (CONFIG_FILES.some((f) => f.path === path) || OWNED_FILES.some((f) => f.path === path)) return true;
  return [...Object.values(AGENT_DIRS), ...Object.values(SKILL_MIRRORS)].some((dir) => path.startsWith(`${dir}/eos-`));
}

const readText = (root, rel) => { try { return readFileSync(join(root, rel), 'utf8'); } catch { return null; } };
const canonical = (doc) => JSON.stringify(doc);

/**
 * What `eos agents sync` would do for the agent-platform files. Pure: reads, writes nothing.
 * @returns {{rows: Array<{path:string, action:'current'|'add'|'update'|'remove', platform:string, content?:string, mode?:number}>, problems: string[]}}
 */
export function planPlatformSync(root, platforms) {
  const declared = new Set(platforms);
  const rows = [];
  const problems = [];
  const wantedBy = (list) => list.filter((p) => declared.has(p));

  for (const file of CONFIG_FILES) {
    const wanted = file.pieces.filter((p) => wantedBy(p.platforms).length);
    const owners = [...new Set(file.pieces.flatMap((p) => p.platforms))];
    const platform = (wantedBy(owners).length ? wantedBy(owners) : owners).join(',');
    const link = linkOnPath(root, file.path);
    if (link) {
      if (wanted.length) problems.push(`${link} is a symbolic link — EOS never writes through a link; replace it with a real file or directory to configure ${platform}`);
      continue;
    }
    const text = readText(root, file.path);
    if (text === null && !wanted.length) continue;
    try {
      if (file.toml) {
        let next = text ?? '';
        for (const p of file.pieces) next = wanted.includes(p) ? p.set(next) : p.unset(next);
        if (text === null) rows.push({ platform, path: file.path, action: 'add', content: next });
        else if (next === text) rows.push({ platform, path: file.path, action: 'current' });
        else rows.push({ platform, path: file.path, action: next.trim() ? 'update' : 'remove', ...(next.trim() ? { content: next } : {}) });
        continue;
      }
      let doc = {};
      if (text !== null) {
        try { doc = JSON.parse(text); } catch (e) { throw new Error(`is not plain JSON (${e.message}) — add the EOS entry by hand, or remove the comments`); }
        if (!isObject(doc)) throw new Error('is not a JSON object');
      }
      const next = clone(doc);
      if (text === null && file.skeleton) Object.assign(next, clone(file.skeleton));
      for (const p of file.pieces) (wanted.includes(p) ? p.set : p.unset)(next);
      const empty = Object.keys(next).length === 0 || (file.skeleton && canonical(next) === canonical(file.skeleton));
      if (text === null) rows.push({ platform, path: file.path, action: 'add', content: `${JSON.stringify(next, null, 2)}\n` });
      else if (canonical(next) === canonical(doc)) rows.push({ platform, path: file.path, action: 'current' });
      else if (empty) rows.push({ platform, path: file.path, action: 'remove' });
      else rows.push({ platform, path: file.path, action: 'update', content: `${JSON.stringify(next, null, 2)}\n` });
    } catch (e) {
      problems.push(`${file.path} ${e.message}`);
    }
  }

  const owned = (path, platform, want, content, mode) => {
    const link = linkOnPath(root, path);
    if (link) { if (want) problems.push(`${link} is a symbolic link — EOS never writes through a link; replace it to configure ${platform}`); return; }
    const have = readText(root, path);
    if (want) rows.push({ platform, path, action: have === null ? 'add' : have === content ? 'current' : 'update', content, ...(mode ? { mode } : {}) });
    else if (have !== null) rows.push({ platform, path, action: 'remove' });
  };
  for (const f of OWNED_FILES) owned(f.path, f.platforms.join(','), wantedBy(f.platforms).length > 0, f.content(), f.mode);

  const agents = sourceAgents(root);
  for (const [platform, dir] of Object.entries(AGENT_DIRS)) {
    const want = declared.has(platform);
    const names = new Set();
    for (const a of agents) {
      const path = `${dir}/${agentFile[platform](a.name)}`;
      names.add(path);
      owned(path, platform, want, renderAgent[platform](a));
    }
    // An eos- agent no source produces any more is EOS's to remove; a team's own agents stay.
    if (!linkOnPath(root, dir) && existsSync(join(root, dir))) {
      for (const f of readdirSync(join(root, dir)).filter((n) => /^eos-/.test(n)).sort()) {
        const path = `${dir}/${f}`;
        if (!names.has(path) && readText(root, path)?.includes(GENERATED_MARK)) rows.push({ platform, path, action: 'remove' });
      }
    }
  }
  return { rows: rows.sort((a, b) => a.path.localeCompare(b.path)), problems };
}

/** Carry out a plan's platform rows. */
export function applyPlatformSync(root, rows) {
  for (const r of rows) {
    const full = join(root, r.path);
    const link = linkOnPath(root, r.path);
    if (link) throw new Error(`${link} is a symbolic link — not writing ${r.path} through it`);
    if (r.action === 'add' || r.action === 'update') {
      mkdirSync(dirname(full), { recursive: true });
      writeFileSync(full, r.content);
      if (r.mode) chmodSync(full, r.mode);
    } else if (r.action === 'remove') {
      try { unlinkSync(full); } catch (e) { if (e.code !== 'ENOENT') throw e; }
    }
  }
  return rows;
}

/** `--platform x[,y]`: names checked against what EOS knows. */
export function parsePlatformFlag(value) {
  const names = [].concat(value ?? []).flatMap((v) => String(v).split(',')).map((s) => s.trim()).filter(Boolean);
  const unknown = names.filter((n) => !AGENT_PLATFORMS.includes(n));
  return { names: [...new Set(names)], unknown };
}
